WITH matched_keys AS (SELECT merchant, id FROM transactions EXCEPT SELECT merchant, id FROM transactions WHERE HOUR(txn_time) BETWEEN 9 AND 12), kept_rows AS (SELECT s.* FROM transactions s JOIN matched_keys k ON s.merchant = k.merchant AND s.id = k.id) SELECT DATE_TRUNC('QUARTER', txn_time) AS quarter_start, account_id, MIN(txn_time) AS first_txn_time, MAX(txn_time) AS last_seen, AVG(amount) FILTER (WHERE txn_type = 'DEBIT') AS debit_avg_amount FROM kept_rows GROUP BY DATE_TRUNC('QUARTER', txn_time), account_id ORDER BY quarter_start ASC;
